impl crate::ClientSide for ClientRole {}

/// `M_Mount::Client`: receives [`ClientMessage`], sends [`ServiceMessage`].
pub type Client = crate::Endpoint<ClientRole>;

/// Typed senders, one per outgoing operation. They encode straight from borrowed data.
impl crate::Endpoint<ClientRole> {
    /// Configure the maximum rate of movement for a Mount platform
    /// (angular velocity soft limits).
    pub fn config_maximum_rate(&self, azimuth_rate: &crate::common::AngleRateDegreesPerSecOptionalType, elevation_rate: &crate::common::AngleRateDegreesPerSecOptionalType) -> crate::Result<()> {
        let mut w = Writer::default();
        azimuth_rate.encode(&mut w);
        elevation_rate.encode(&mut w);
        self.send_raw(0, w.as_bytes())
    }

    /// Determine source for inputs.
    ///
    /// Note: Input data should only be handled by the mount from the configured clients.
    /// Input data from other clients should be ignored.
    /// If a filter is disabled, all inputs are allowed.
    /// If a filter is enabled, all inputs in the according list are allowed (white list).
    /// (Therefore, an enabled filter in combination with an empty list inhibits all input.)
    pub fn config_input_source(&self, is_client_id_filter_enabled: bool, client_ids: &crate::common::StringListType) -> crate::Result<()> {
        let mut w = Writer::default();
        is_client_id_filter_enabled.encode(&mut w);
        client_ids.encode(&mut w);
        self.send_raw(1, w.as_bytes())
    }

    /// Determine source for target assignment inputs.
    ///
    /// Note: Input data should only be handled by the mount from the configured clients.
    /// Input data from other clients should be ignored.
    /// If a filter is disabled, all inputs are allowed.
    /// If a filter is enabled, all inputs in the according list are allowed (white list).
    /// (Therefore, an enabled filter in combination with an empty list inhibits all input.)
    pub fn config_tgt_assignment_input_source(&self, is_tgt_assignment_client_id_filter_enabled: bool, tgt_assignment_client_ids: &crate::common::StringListType) -> crate::Result<()> {
        let mut w = Writer::default();
        is_tgt_assignment_client_id_filter_enabled.encode(&mut w);
        tgt_assignment_client_ids.encode(&mut w);
        self.send_raw(2, w.as_bytes())
    }

    /// Determine source for target assignment search inputs.
    ///
    /// Note: Input data should only be handled by the mount from the configured clients.
    /// Input data from other clients should be ignored.
    /// If a filter is disabled, all inputs are allowed.
    /// If a filter is enabled, all inputs in the according list are allowed (white list).
    /// (Therefore, an enabled filter in combination with an empty list inhibits all input.)
    pub fn config_tgt_assignment_search_input_source(&self, is_tgt_assignment_search_client_id_filter_enabled: bool, tgt_assignment_search_client_ids: &crate::common::StringListType) -> crate::Result<()> {
        let mut w = Writer::default();
        is_tgt_assignment_search_client_id_filter_enabled.encode(&mut w);
        tgt_assignment_search_client_ids.encode(&mut w);
        self.send_raw(3, w.as_bytes())
    }

    /// Configure the search area around the Target Assignment position.
    ///
    /// Note: This should be stored and used when searching around a position in
    /// provided "NotifyTgtAssignmentCart" or "NotifyTgtAssignmentSphere" in
    /// "Target_Assignment" Control Mode.
    pub fn config_tgt_assignment_search_pattern(&self, search_pattern_params: &TgtAssignmentSearchPatternType) -> crate::Result<()> {
        let mut w = Writer::default();
        search_pattern_params.encode(&mut w);
        self.send_raw(4, w.as_bytes())
    }

    /// Configure the internal device that the Mount shall be slaved to.
    /// If value is not present, no leading device shall be used to slave to.
    ///
    /// Note: This should be stored and used when in "Slaved_To_Leading_Device"
    /// Control Mode.
    pub fn config_leading_device(&self, device_id: &crate::common::LongOptionalType) -> crate::Result<()> {
        let mut w = Writer::default();
        device_id.encode(&mut w);
        self.send_raw(5, w.as_bytes())
    }

    /// Configure the internal device that shall be slaved to the Mount.
    /// If value is not present, no slaving device shall be used.
    pub fn config_slaved_device(&self, device_id: &crate::common::LongOptionalType) -> crate::Result<()> {
        let mut w = Writer::default();
        device_id.encode(&mut w);
        self.send_raw(6, w.as_bytes())
    }

    /// Configure the azimuth/elevation slew limits.
    /// If slew limitation is specified the Mount service uses the provided limits,
    /// otherwise the hard limits of the Mount will be used.
    pub fn config_slew_limits(&self, slew_limits: &AngularLimitType) -> crate::Result<()> {
        let mut w = Writer::default();
        slew_limits.encode(&mut w);
        self.send_raw(7, w.as_bytes())
    }

    /// Store a mount position, identified by a string key.
    /// This is meant to quickly access positions of interest for later use.
    pub fn config_store_position(&self, key_id: &str, azimuth: crate::common::AngleDegreesType, elevation: crate::common::AngleDegreesType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        key_id.encode(&mut w);
        azimuth.encode(&mut w);
        elevation.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(8, w.as_bytes())
    }

    /// Move to an earlier assigned or persistently stored mount position, identified by a string key.
    pub fn cmd_move_to_stored_position(&self, id: &str) -> crate::Result<()> {
        let mut w = Writer::default();
        id.encode(&mut w);
        self.send_raw(9, w.as_bytes())
    }

    /// Command to set mode of control and stabilization for a Mount platform.
    ///
    /// Note: The Mount will use stored data from previously provided config calls when required
    /// as parameters for the specified Mode.
    pub fn cmd_mode(&self, mode: ModeCommand) -> crate::Result<()> {
        let mut w = Writer::default();
        mode.encode(&mut w);
        self.send_raw(10, w.as_bytes())
    }

    /// Control Target Assignment search action.
    ///
    /// Note: Command is only processed when the Mount is in the "Target_Assignment" Control Mode.
    pub fn cmd_tgt_assignment_search_action(&self, action: TgtAssignmentSearchCmdKind) -> crate::Result<()> {
        let mut w = Writer::default();
        action.encode(&mut w);
        self.send_raw(11, w.as_bytes())
    }

    /// Command to the Mount service to enable or disable automatic drift compensation correction.
    /// This is used to correct a drifting Mount platform. It uses offset values automatically
    /// determined by the Mount platform.
    pub fn cmd_auto_drift_compensation(&self, is_enabled: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        is_enabled.encode(&mut w);
        self.send_raw(12, w.as_bytes())
    }

    /// Command to manually set the specified drift compensation offset.
    /// This is used to set the offset values to correct a drifting Mount.
    pub fn cmd_manual_drift_compensation(&self, offset_azimuth_rate: crate::common::AngleRateDegreesPerSecType, offset_elevation_rate: crate::common::AngleRateDegreesPerSecType, is_relative: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        offset_azimuth_rate.encode(&mut w);
        offset_elevation_rate.encode(&mut w);
        is_relative.encode(&mut w);
        self.send_raw(13, w.as_bytes())
    }

    /// Command to allow external sources to set drift compensation.
    pub fn cmd_allow_external_drift_compensation(&self, is_allowed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        is_allowed.encode(&mut w);
        self.send_raw(14, w.as_bytes())
    }

    /// Command to aim perfectly aligned with the horizon line by compensating vehicle attitude.
    pub fn cmd_horizontal_aiming(&self, is_enabled: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        is_enabled.encode(&mut w);
        self.send_raw(15, w.as_bytes())
    }

    /// Sets operational mode RateAid calculation.
    pub fn cmd_set_operational_mode_rate_aid(&self, activate: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        activate.encode(&mut w);
        self.send_raw(16, w.as_bytes())
    }

    /// Notify the Mount to turn to a position angle in degrees.
    ///
    /// Note: This operation shall be called only if the InputSourceClientId matches with the
    /// MountStatusType.InputSourceClientId of ReportMountStatus().
    pub fn notify_angle(&self, input_source_client_id: &str, azimuth: crate::common::AngleDegreesType, elevation: crate::common::AngleDegreesType, angle_params: &MountAngleParamsType) -> crate::Result<()> {
        let mut w = Writer::default();
        input_source_client_id.encode(&mut w);
        azimuth.encode(&mut w);
        elevation.encode(&mut w);
        angle_params.encode(&mut w);
        self.send_raw(17, w.as_bytes())
    }

    /// Designate the Mount to position for a target assignment.
    /// The Mount will follow the object automatically between updates by using the provided object velocity.
    ///
    /// Note: This operation shall be called only if the InputSourceClientId matches with the
    /// MountStatusType.InputSourceClientId of ReportMountStatus().
    pub fn notify_tgt_assignment(&self, input_source_client_id: &str, position: &crate::common::PositionType, velocity: &crate::common::LinearVelocityOptionalType, timestamp: &crate::common::TimeType, angle_params: &MountAngleParamsType) -> crate::Result<()> {
        let mut w = Writer::default();
        input_source_client_id.encode(&mut w);
        position.encode(&mut w);
        velocity.encode(&mut w);
        timestamp.encode(&mut w);
        angle_params.encode(&mut w);
        self.send_raw(18, w.as_bytes())
    }

    /// Command to set relative rate of movement for a Mount platform.
    /// A value of 0 keeps the current Mount movement. A positive value speeds up
    /// or negative value slows down the Mount movement in one direction. A negative
    /// value speeds up or a positive value slows down the movement in the opposite
    /// direction.
    ///
    /// Note: This is implemented as a notify call in order to always contain the
    /// latest value from a client.
    ///
    /// Note: This operation shall be called only if the InputSourceClientId matches with the
    /// MountStatusType.InputSourceClientId of ReportMountStatus().
    pub fn notify_rate_relative(&self, input_source_client_id: &str, azimuth_rate: crate::common::AngleRateDegreesPerSecType, elevation_rate: crate::common::AngleRateDegreesPerSecType) -> crate::Result<()> {
        let mut w = Writer::default();
        input_source_client_id.encode(&mut w);
        azimuth_rate.encode(&mut w);
        elevation_rate.encode(&mut w);
        self.send_raw(19, w.as_bytes())
    }

    /// Command to set absolute rate of movement for a Mount platform.
    /// A value of 0 stops the Mount from moving. A negative value moves the Mount
    /// in the other direction.
    ///
    /// Note: This is implemented as a notify call in order to always contain the
    /// latest value from a client.
    ///
    /// Note: This operation shall be called only if the InputSourceClientId matches with the
    /// MountStatusType.InputSourceClientId of ReportMountStatus().
    pub fn notify_rate_absolute(&self, input_source_client_id: &str, azimuth_rate: crate::common::AngleRateDegreesPerSecType, elevation_rate: crate::common::AngleRateDegreesPerSecType) -> crate::Result<()> {
        let mut w = Writer::default();
        input_source_client_id.encode(&mut w);
        azimuth_rate.encode(&mut w);
        elevation_rate.encode(&mut w);
        self.send_raw(20, w.as_bytes())
    }

    /// Provides the Mount with normed rate of movement.
    /// This sets the rate of movement normed to the maximum possible rate
    /// of the Mount. A value of 0 stops the Mount from moving. A value of
    /// 1 or -1 moves the Mount at the maximum rate. A negative value
    /// moves the Mount in the opposite direction.
    ///
    /// Note: This is implemented as a notify call in order to always contain the
    /// latest value from a client. This can then correspond to an output report
    /// from a joystick.
    ///
    /// Note: This operation shall be called only if the InputSourceClientId matches with the
    /// MountStatusType.InputSourceClientId of ReportMountStatus().
    pub fn notify_rate_scaled(&self, input_source_client_id: &str, scaled_rate: &ScaledRateOptionalType) -> crate::Result<()> {
        let mut w = Writer::default();
        input_source_client_id.encode(&mut w);
        scaled_rate.encode(&mut w);
        self.send_raw(21, w.as_bytes())
    }

}

